-- ═══════════════════════════════════════════════════════════════
-- 1. Rater puis retenter ne doit pas rejouer le même quiz.
--
-- Il n'y avait que 6 questions de certification par compétence, et le quiz
-- en tire 5 : un élève qui rate et clique « Relire la fiche et retenter »
-- retombait sur cinq des six mêmes. Au deuxième essai il ne réapprenait pas
-- le geste, il se souvenait de la case (audit du 01/08/2026).
--
-- 18 questions de plus sur les trois compétences que tout le monde traverse
-- en premier, et qui sont aussi les seules ouvertes au compte gratuit :
-- C1a, C1b, C1c passent de 6 à 12 ou 13. Elles valent pour les deux boîtes
-- (colonne `boite` à NULL).
--
-- Reste à faire : les 28 autres compétences.
--
-- 2. Les tirets longs oubliés en base.
--
-- Le balayage du 31/07 (« zéro tiret ») n'a nettoyé que le dépôt. La banque
-- de questions vit en base : 9 questions et 22 traductions portaient encore
-- un « — ». La base est une surface publique de plus, au même titre que les
-- pages hors `src/`.
-- ═══════════════════════════════════════════════════════════════

on conflict (id) do nothing;

on conflict (question_id, lang) do nothing;

-- ── Les tirets longs de la banque de questions ────────────────────
-- Français réécrit à la main (une incise se coupe dans la langue, pas
-- mécaniquement), traductions ramenées à la virgule.
update public.questions_competence set explanation = replace(explanation, ' — et jamais', '. Et jamais') where id='142e097a-2ec2-415c-8dc7-7798b87f7238';
update public.questions_competence set explanation = replace(explanation, ' — les yeux seuls', '. Les yeux seuls') where id='ca4bd680-d6fe-48f8-9534-d6f24fc2ad1b';
update public.questions_competence set explanation = replace(explanation, ' — jamais tout ou rien', ', jamais tout ou rien') where id='ddbd9068-e4fa-4435-b8a1-fb7cb7770b3b';
update public.questions_competence set explanation = replace(explanation, ' — ceux qui en sortent', '. Ceux qui en sortent') where id='0aad5f09-384f-4484-bbcc-c2bc48870612';
update public.questions_competence set explanation = replace(explanation, ' — il t''en voudra', '. Il t''en voudra') where id='feb299c0-5d8d-4cc9-af66-ec5f9d8648a0';
update public.questions_competence set explanation = replace(explanation, ' — et moins il boit', ', et moins il boit') where id='790e45bf-5409-4523-b902-a246f993645b';
update public.questions_competence set explanation = replace(explanation, ' — tu étais déjà prêt', ', tu étais déjà prêt') where id='b6958820-6684-4879-b8bd-e748ffed0956';
update public.questions_competence
set explanation = $pg$Le klaxon n'est pas banni. Il sert à prévenir d'un danger immédiat, et à rien d'autre.$pg$
where id = 'd5e744e0-271f-4462-adcb-bbf2ad5fc2a1';

update public.questions_competence set
  question = replace(question, ' — ', ', '),
  explanation = replace(explanation, ' — ', ', '),
  options = replace(options::text, ' — ', ', ')::jsonb
where question like '%—%' or explanation like '%—%' or options::text like '%—%';

update public.question_translations set
  question = replace(question, ' — ', case when lang='ar' then '، ' else ', ' end),
  explanation = replace(explanation, ' — ', case when lang='ar' then '، ' else ', ' end),
  options = replace(options::text, ' — ', case when lang='ar' then '، ' else ', ' end)::jsonb
where question like '%—%' or explanation like '%—%' or options::text like '%—%';
